export function communityUI(lang: Language) {
  const d = DICT[lang];
  return (key: CommunityUIKey): string => (d && d[key]) || EN[key];
}

const CATEGORY_KEY: Record<RecommendationCategory, CommunityUIKey> = {
  food: "cat_food",
  stay: "cat_stay",
  activity: "cat_activity",
  guide: "cat_guide",
  tip: "cat_tip",
};

export function categoryUIKey(category: RecommendationCategory): CommunityUIKey {
  return CATEGORY_KEY[category];
}

const OUTCOME_KEY: Record<VisaOutcome, CommunityUIKey> = {
  approved: "outcome_approved",
  denied: "outcome_denied",
  rfe: "outcome_rfe",
  pending: "outcome_pending",
};

export function outcomeUIKey(outcome: VisaOutcome): CommunityUIKey {
  return OUTCOME_KEY[outcome];
}
